  "confidence": "high",
  "narrative": "Starting from the Mediterranean fatality reference class, the observed pace through February 2026 implies a steep trajectory toward 1,000+ deaths by May. Factoring in seasonal risk and SAR dynamics, the posterior probability remains extremely high, though not certain due to reporting lags and possible mitigations.",
  "justification": {
    "anchor": {
      "probability": 0.70,
      "basis": "Reference class is annual Central Mediterranean fatalities; anchor around 0.70 reflects that ongoing high pace and historical context support a near-certain outcome within the window, but not guaranteed."
    },
    "factor_updates": [
      {
        "factor": "Current pace of Mediterranean fatalities in early 2026",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths/missing by late February 2026 indicates a pace that, if sustained into March–April, would surpass 1,000 before May."
      },
      {
        "factor": "Spring-season migration and crossing conditions",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Warmer weather and increased crossing attempts historically raise the annual fatalities pace."
      },
      {
        "factor": "Search-and-rescue capacity and policy changes affecting crossings",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Enhanced SAR or policy changes enabling safer rescues could reduce fatalities and push counts below the 1,000 mark."
      }
    ],
    "synthesis_rationale": "Starting from anchor ~0.70, the strong upward momentum from pace dominates, with seasonal uptick further pushing risk upward while SAR improvements provide a moderating downward pressure. The calibration yields a posterior near 0.99, acknowledging data lag and small but nontrivial uncertainty about whether pace sustains through April."
  }
}

